import * as yup from "yup";
export const postJobSchema = yup.object().shape({
  jobTitle: yup.string().required("Job title is required").min(3, "Too short — at least 3 characters"),
  organization: yup.string().required("Organization name is required").min(2, "Too short — at least 2 characters"),
  rate: yup.number().typeError("Rate must be a number").required("Please enter rate").positive("Rate must be positive"),
  skills: yup.string().required("Please add at least one skill"),
  description: yup.string().required("Description is required").min(10, "Add more details about the job")
});
